#include <algorithm>
#include <cstddef>
#include <string>
#include <utility>
#include <vector>

struct Student
{
    std::string name{};
};

class Classroom
{
public:
    explicit Classroom(std::string name) : m_name{ std::move(name) } {}

    const std::string& name() const { return m_name; }
    void enrol(Student& student) { if (!has(student)) m_students.push_back(&student); }
    std::size_t studentCount() const { return m_students.size(); }
    bool has(const Student& student) const { return std::find(m_students.begin(), m_students.end(), &student) != m_students.end(); }

private:
    std::string m_name{};
    std::vector<const Student*> m_students{};
};

class School
{
public:
    School() { m_rooms.reserve(16); }

    Classroom& addClassroom(std::string name)
    {
        m_rooms.emplace_back(std::move(name));
        return m_rooms.back();
    }

    std::size_t classroomCount() const { return m_rooms.size(); }

    std::size_t totalEnrolments() const
    {
        std::size_t total{ 0 };
        for (const Classroom& room : m_rooms)
        {
            total += room.studentCount();
        }
        return total;
    }

    const Classroom* roomOf(const Student& student) const
    {
        for (const Classroom& room : m_rooms)
        {
            if (room.has(student))
            {
                return &room;
            }
        }
        return nullptr;
    }

private:
    std::vector<Classroom> m_rooms{};
};

unitTests:
TEST("classrooms aggregate students") { Student a{ "Ann" }, b{ "Bo" }; Classroom c{ "Maths" }; c.enrol(a); c.enrol(b); c.enrol(a); CHECK_EQ(c.name(), "Maths"); CHECK_EQ(c.studentCount(), 2u); CHECK(c.has(b)); }
TEST("a school owns its classrooms") { School s{}; Classroom& maths{ s.addClassroom("Maths") }; Classroom& art{ s.addClassroom("Art") }; CHECK_EQ(s.classroomCount(), 2u); CHECK_EQ(maths.name(), "Maths"); CHECK_EQ(art.name(), "Art"); }
TEST("enrolments are counted across rooms") { Student a{ "Ann" }, b{ "Bo" }; School s{}; Classroom& maths{ s.addClassroom("Maths") }; Classroom& art{ s.addClassroom("Art") }; maths.enrol(a); maths.enrol(b); art.enrol(a); CHECK_EQ(s.totalEnrolments(), 3u); }
TEST("roomOf") { Student a{ "Ann" }, b{ "Bo" }, c{ "Cy" }; School s{}; Classroom& maths{ s.addClassroom("Maths") }; Classroom& art{ s.addClassroom("Art") }; maths.enrol(a); art.enrol(b); art.enrol(a); const Classroom* r{ s.roomOf(b) }; CHECK(r != nullptr); if (r) CHECK_EQ(r->name(), "Art"); const Classroom* first{ s.roomOf(a) }; CHECK(first != nullptr); if (first) CHECK_EQ(first->name(), "Maths"); CHECK(s.roomOf(c) == nullptr); }
TEST("references stay valid as rooms are added") { School s{}; Classroom& first{ s.addClassroom("Room 0") }; for (int i{ 1 }; i < 16; ++i) s.addClassroom("Room " + std::to_string(i)); CHECK_EQ(first.name(), "Room 0"); CHECK_EQ(s.classroomCount(), 16u); }

